import{_ as e,o as a,c as r,a3 as o}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"Testing Flows","description":"The testing options in the Flow editor and how to narrow down errors.","frontmatter":{"title":"Testing Flows","description":"The testing options in the Flow editor and how to narrow down errors."},"headers":[],"relativePath":"en/flows/testen.md","filePath":"en/flows/testen.md","lastUpdated":1787319236000}'),s={name:"en/flows/testen.md"};function i(n,t,d,l,h,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="testing-flows" tabindex="-1">Testing Flows <a class="header-anchor" href="#testing-flows" aria-label="Permalink to &quot;Testing Flows&quot;">​</a></h1><p>A Flow touches real data and sends real messages. Test it before it reacts to live events.</p><div class="danger custom-block"><p class="custom-block-title">A test run is not a dry run</p><p>A test <strong>actually</strong> executes the Flow: emails go out, entries are created and changed, outside systems get called.</p><p>Use your own email address and test records when testing — not real customer data.</p></div><h2 id="the-test-types" tabindex="-1">The test types <a class="header-anchor" href="#the-test-types" aria-label="Permalink to &quot;The test types&quot;">​</a></h2><p>The editor offers several ways to run a Flow:</p><table tabindex="0"><thead><tr><th>Button</th><th>Description in the interface</th></tr></thead><tbody><tr><td><strong>Run Flow</strong></td><td>Starts the Flow</td></tr><tr><td><strong>Test Flow</strong></td><td><em>Uses the last row of the Grid</em></td></tr><tr><td><strong>Restart</strong></td><td><em>With data from the last execution</em></td></tr><tr><td><strong>Start with test data</strong></td><td><em>Provide sample data</em></td></tr><tr><td><strong>Wait</strong></td><td><em>Wait until the Flow runs again</em></td></tr><tr><td><strong>With data from the Flow form</strong></td><td><em>Open the form and test with submitted data</em></td></tr></tbody></table><h3 id="test-flow" tabindex="-1">Test Flow <a class="header-anchor" href="#test-flow" aria-label="Permalink to &quot;Test Flow&quot;">​</a></h3><p>The fastest way. Takes the last row of the Grid as input.</p><div class="tip custom-block"><p class="custom-block-title">Keep a test row in place</p><p>Since it always uses the <em>last</em> row, it&#39;s worth maintaining a test record at the very bottom of the Grid — with your own email address and clearly recognizable values like <code>TEST Smith</code>.</p></div><h3 id="restart" tabindex="-1">Restart <a class="header-anchor" href="#restart" aria-label="Permalink to &quot;Restart&quot;">​</a></h3><p>Repeats the Flow with the data from the last run. Ideal when fixing an error: you change a setting and re-run the same input data.</p><p>If there was no previous run yet, the editor reports <em>No previous execution found.</em></p><h3 id="start-with-test-data" tabindex="-1">Start with test data <a class="header-anchor" href="#start-with-test-data" aria-label="Permalink to &quot;Start with test data&quot;">​</a></h3><p>You provide the input data yourself as a sample. The right approach for the <strong>Webhook</strong> trigger, where the data would otherwise come from outside.</p><h3 id="wait" tabindex="-1">Wait <a class="header-anchor" href="#wait" aria-label="Permalink to &quot;Wait&quot;">​</a></h3><p>The editor waits for the next real run and shows its data. Useful for observing what happens during actual use.</p><h3 id="with-data-from-the-flow-form" tabindex="-1">With data from the Flow form <a class="header-anchor" href="#with-data-from-the-flow-form" aria-label="Permalink to &quot;With data from the Flow form&quot;">​</a></h3><p>Opens the associated form. What you submit there becomes the test input. The most realistic test for form-based Flows.</p><h2 id="is-the-flow-even-ready-to-test" tabindex="-1">Is the Flow even ready to test? <a class="header-anchor" href="#is-the-flow-even-ready-to-test" aria-label="Permalink to &quot;Is the Flow even ready to test?&quot;">​</a></h2><p>If everything is fully configured, the editor reports:</p><blockquote><p><em>The Flow is ready to be tested</em></p></blockquote><p>If something&#39;s missing, this appears instead:</p><blockquote><p><em>Flow still has errors</em></p></blockquote><p>Go through the steps then — an incompletely configured step is marked in the editor.</p><h2 id="viewing-results" tabindex="-1">Viewing results <a class="header-anchor" href="#viewing-results" aria-label="Permalink to &quot;Viewing results&quot;">​</a></h2><p>After a run, the editor shows the data of that run. The hint reads <em>Displaying previous executions</em> — so you&#39;re not looking at the blueprint, but at concrete values.</p><p>Displayed are the execution time, status, and number of steps. <strong>Select other</strong> jumps to a different run, <strong>Reset</strong> leaves this view.</p><p>Run status values:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Completed</strong> / <em>Done</em></td><td>Ran through fully</td></tr><tr><td><strong>Failed</strong> / <em>Error</em></td><td>Aborted</td></tr><tr><td><strong>In progress</strong></td><td>Currently running</td></tr><tr><td><strong>Waiting</strong></td><td>Waiting on an event, e.g. page input</td></tr><tr><td><strong>Test run</strong></td><td>A test run, not a real execution</td></tr></tbody></table><h2 id="narrowing-down-errors" tabindex="-1">Narrowing down errors <a class="header-anchor" href="#narrowing-down-errors" aria-label="Permalink to &quot;Narrowing down errors&quot;">​</a></h2><p>On every step, <strong>Show details</strong> leads to input and output data, and on problems, <strong>Show error details</strong> leads to the error message.</p><p>A tried-and-tested approach:</p><ol><li><strong>Where does it break off?</strong> The history shows how many steps ran.</li><li><strong>What came in?</strong> Check the output at the last successful step via <em>Show details</em>.</li><li><strong>What did the failing step expect?</strong> Often a field doesn&#39;t match the expected format.</li><li><strong>Change and repeat with &quot;Restart&quot;.</strong> Same input, changed configuration.</li></ol><h2 id="common-causes" tabindex="-1">Common causes <a class="header-anchor" href="#common-causes" aria-label="Permalink to &quot;Common causes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th></tr></thead><tbody><tr><td>Flow doesn&#39;t start at all</td><td>Trigger points to a different Grid or form than intended</td></tr><tr><td>Flow suddenly stops starting</td><td>The <a href="/en/flows/was-ist-ein-flow#switching-on-and-off">switch</a> is set to <em>off</em> — possibly <a href="/en/flows/durchlaufhistorie#error-notifications">automatically after three identical errors</a></td></tr><tr><td>Flow starts too often</td><td><em>Entry was changed</em> without a field condition</td></tr><tr><td>Flow starts endlessly</td><td>An action writes to the same Grid that triggers the Flow</td></tr><tr><td>Email doesn&#39;t arrive</td><td>Recipient field empty because the field value wasn&#39;t set</td></tr><tr><td>Empty values in the message</td><td>Reference to a step that hasn&#39;t delivered anything yet</td></tr><tr><td>Only one entry instead of many</td><td><em>Load all entries</em> without a following <strong>Parallel</strong></td></tr><tr><td><em>Flow still has errors</em></td><td>A step is incompletely configured</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Break infinite loops</p><p>If a Flow triggers itself, runs keep piling up. Switch it off first via the <a href="/en/flows/was-ist-ein-flow#switching-on-and-off">switch</a> — this stops immediately, including runs currently in progress. Then calmly change the trigger or the target of the writing action, switch it back on, and check the history to make sure no new runs are being created.</p></div><h2 id="before-going-live" tabindex="-1">Before going live <a class="header-anchor" href="#before-going-live" aria-label="Permalink to &quot;Before going live&quot;">​</a></h2><p>A short checklist:</p><ul><li>[ ] Test run completed without errors</li><li>[ ] Tested a real submission, not just the editor test</li><li>[ ] Recipient addresses checked — no test addresses left</li><li>[ ] For writing actions: no possibility of self-triggering</li><li>[ ] For webhook triggers: URL not stored somewhere publicly accessible</li><li>[ ] Test records removed from the Grid</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/flows/durchlaufhistorie">Run history</a></li><li><a href="/en/flows/daten-zwischen-schritten">Data between steps</a></li><li><a href="/en/fehlerbehebung/haeufige-fehlermeldungen">Common error messages</a></li></ul>',41)])])}const m=e(s,[["render",i]]);export{p as __pageData,m as default};
